package main

import (
	"testing"
)

func TestGenerate(t *testing.T) {
	tests := []struct {
		name string
		srcs map[string]string
		exp  string
		err  bool
	}{
		{
			"type and fields",
			map[string]string{"a.go": "package main\n\n// App is the app.\n//\n// Usage:\n//\n//\tapp [flags]\ntype App struct {\n\t// Name is the name, with a comma.\n\tName string `ox:\",short:n\"`\n\tA, B int\n\t// C and D.\n\tC, D int\n}\n"},
			"// Code generated by oxdoc. DO NOT EDIT.\n\npackage main\n\nimport \"github.com/xo/ox\"\n\nfunc init() {\n\tox.RegisterDoc[App](\"App is the app.\\n\\nUsage:\\n\\n\\tapp [flags]\\n\", map[string]string{\n\t\t\"Name\": \"Name is the name, with a comma.\\n\",\n\t\t\"C\":    \"C and D.\\n\",\n\t\t\"D\":    \"C and D.\\n\",\n\t})\n}\n",
			false,
		},
		{
			"doc on the declaration",
			map[string]string{"a.go": "package app\n\n// App is the app.\ntype App struct{}\n\ntype (\n\t// B is b.\n\tB struct{}\n\tC struct{}\n)\n"},
			"// Code generated by oxdoc. DO NOT EDIT.\n\npackage app\n\nimport \"github.com/xo/ox\"\n\nfunc init() {\n\tox.RegisterDoc[App](\"App is the app.\\n\", nil)\n\tox.RegisterDoc[B](\"B is b.\\n\", nil)\n}\n",
			false,
		},
		{
			"no doc and generic types",
			map[string]string{"a.go": "package main\n\ntype App struct{}\n\n// G is generic.\ntype G[T any] struct{}\n\n// I is not a struct.\ntype I int\n"},
			"// Code generated by oxdoc. DO NOT EDIT.\n\npackage main\n",
			false,
		},
		{
			"two files in order",
			map[string]string{"b.go": "package main\n\n// B is b.\ntype B struct{}\n", "a.go": "package main\n\n// A is a.\ntype A struct{}\n"},
			"// Code generated by oxdoc. DO NOT EDIT.\n\npackage main\n\nimport \"github.com/xo/ox\"\n\nfunc init() {\n\tox.RegisterDoc[A](\"A is a.\\n\", nil)\n\tox.RegisterDoc[B](\"B is b.\\n\", nil)\n}\n",
			false,
		},
		{"two packages", map[string]string{"a.go": "package a\n", "b.go": "package b\n"}, "", true},
		{"a syntax error", map[string]string{"a.go": "package a\n\ntype\n"}, "", true},
		{"no file", nil, "", true},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			srcs := make(map[string][]byte)
			for name, src := range test.srcs {
				srcs[name] = []byte(src)
			}
			buf, err := Generate(srcs)
			switch {
			case test.err && err == nil:
				t.Fatalf("expected an error")
			case !test.err && err != nil:
				t.Fatalf("expected no error, got: %v", err)
			}
			if s := string(buf); s != test.exp {
				t.Errorf("expected:\n%s\ngot:\n%s\nexpected: %q\ngot:      %q", test.exp, s, test.exp, s)
			}
		})
	}
}
